// Awaker watchroom: every tracked player across leagues, live scoring and score alerts.
import {aggregateWatch} from '../../engine.js';
import {S} from '../state.js';
import {$,colors,empty,esc,fmt,injury,leagueOptions,pageHead,playerPortrait,pname,scoring,signed,teamColors,value} from '../core.js';
import {scoreKey,trackScores} from '../outlook.js';
import {render} from '../render.js';

export function observeScores(){
 const scope=`${S.data.demo?'demo':S.data.user.user_id}:${S.data.nfl?.season}:${S.data.week}`;
 if(scope!==S.scoreScope){S.scoreScope=scope;S.scoreEvents=[];S.previewPlayer=null}
 const changes=trackScores(aggregateWatch(S.data.leagues,S.data.players,S.data.games),scope);
 if(changes.length){const now=Date.now();S.scoreEvents=[...changes.map(a=>({...a,at:now,key:scoreKey(a.id,a)})),...S.scoreEvents].slice(0,40);scheduleScoreCleanup()}
}
export function scheduleScoreCleanup(){clearTimeout(S.scoreTimer);S.scoreTimer=setTimeout(()=>{S.previewPlayer=null;if(S.view==='watch')render()},12000)}
export function recentScore(id,a){return S.scoreEvents.find(e=>e.key===scoreKey(id,a)&&Date.now()-e.at<12000)}
export function scoreActivity(){const events=S.scoreEvents.filter(e=>(S.watchLeague==='all'||e.leagueId===S.watchLeague)&&(S.watchRole==='both'||e.side===S.watchRole)&&(e.starter||S.bench));return `<details class="score-activity"><summary>${events.length?`${events.length} recent score updates · ${esc(pname(events[0].id))} ${signed(events[0].delta)}`:'Score activity · Waiting for the next update'}</summary><div>${events.slice(0,8).map(e=>`<p><time>${new Date(e.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</time><strong>${esc(pname(e.id))}</strong> <span class="${e.side==='opponent'?'attention':'gain'}">${signed(e.delta)}</span> <span>${esc(e.league)}${e.delta<0?' · score correction':''}</span></p>`).join('')||'<p>Score changes appear here after a refresh. Your first sync sets the baseline.</p>'}</div></details>`}
export function leagueCards(){return `<div class="league-grid">${S.data.leagues.filter(l=>l.enabled).map((l,i)=>{const m=l.matchups.find(m=>m.roster_id===l.mine.roster_id),opp=m?.matchup_id==null?null:l.matchups.find(x=>x.matchup_id===m.matchup_id&&x.roster_id!==m.roster_id),r=l.rosters.find(r=>r.roster_id===opp?.roster_id),user=l.users.find(u=>u.user_id===r?.owner_id),playing=(m?.starters||l.mine.starters||[]).filter(id=>S.data.games[S.data.players[id]?.team]?.state==='in').length;const mineNow=m?.custom_points??m?.points,theirsNow=opp?.custom_points??opp?.points,standing=!opp||!(mineNow||theirsNow)?'':mineNow>theirsNow?'winning':mineNow<theirsNow?'trailing':'';return `<article class="league-card ${standing}" style="--league:${colors[i%colors.length]}" ${S.data.demo?'':`data-my-game="${esc(l.league_id)}" role="button" tabindex="0" title="Open both lineups"`}><div class="league-title"><span>${esc(l.name)}</span><small>${scoring(l)}</small></div><div class="match-score"><strong>${fmt(m?.custom_points??m?.points,2)}</strong><span>vs</span><strong class="opponent">${fmt(opp?.custom_points??opp?.points,2)}</strong></div><div class="league-foot"><span>${standing?`<b class="card-standing">${standing==='winning'?'Ahead':'Behind'} by ${fmt(Math.abs(mineNow-theirsNow))}</b> · `:''}vs ${esc(user?.metadata?.team_name||user?.display_name||'No matchup yet')}</span><span>${playing} in live games</span></div></article>`}).join('')}</div>`}
export function watchroom(){const pool=watchedPlayers(),live=pool.filter(p=>p.game?.state==='in').length;return pageHead('Awaker watchroom',`${live} playing now · Every team, one screen.`,`<div class="filters"><button class="secondary" id="score-effects" aria-pressed="${S.prefs.scoreEffects!==false}">Highlights ${S.prefs.scoreEffects===false?'off':'on'}</button><button class="secondary" id="focus">⛶ ${S.focus?'Exit focus':'Focus mode'}</button></div>`)+leagueCards()+`<div class="watch-controls"><div class="filters">${[['auto','Game day'],['live',`Playing now (${live})`],['all','All players'],['upcoming','Up next'],['done','Final'],['pinned','Pinned']].map(([id,label])=>`<button class="filter ${S.filter===id?'active':''}" data-filter="${id}" aria-pressed="${S.filter===id}">${label}</button>`).join('')}<span class="watch-count"><span id="player-count"></span> shown</span></div><div class="watch-selectors"><select class="select" aria-label="Watchroom league" id="watch-league">${leagueOptions(S.watchLeague,true)}</select><select class="select" id="watch-role" aria-label="Players to follow">${[['both','My players + opponents'],['mine','My players only'],['opponent','Opponents only']].map(([v,t])=>`<option value="${v}" ${S.watchRole===v?'selected':''}>${t}</option>`).join('')}</select><input class="search" id="search" value="${esc(S.query)}" placeholder="Player or team…" aria-label="Search players"><select class="week-selector" aria-label="NFL week" id="week">${Array.from({length:18},(_,i)=>`<option value="${i+1}" ${S.data.week===i+1?'selected':''}>Week ${i+1}</option>`).join('')}</select><button class="secondary" id="refresh" ${S.busy?'disabled':''}>${S.busy?'Refreshing…':'↻ Refresh'}</button><label class="checkline"><input type="checkbox" id="bench" ${S.bench?'checked':''}>Show my bench</label></div></div><div class="watch-context"><span>${S.filter==='auto'?(live?'Live games · Points / pregame projection':'No live games · Up next · Points / pregame projection'):'Actual points / pregame projection · league scoring'}</span><button class="inline-btn" id="preview-score">Preview highlight</button></div><div class="watch-grid" id="players">${watchCards(pool)}</div>${scoreActivity()}<p class="watch-footnote">Projections are pregame estimates, not live forecasts. Highlights show changes since the last refresh (about 45s); game live means the NFL game is in progress.</p>`}
export function watchedPlayers(){
 const pool=aggregateWatch(S.data.leagues,S.data.players,S.data.games);
 if(S.filter==='pinned')for(const id of S.pins)if(S.data.players[id]&&!pool.some(p=>p.id===id))pool.push({id,player:S.data.players[id],game:S.data.games[S.data.players[id].team],appearances:S.data.leagues.filter(l=>l.enabled).map(l=>({leagueId:l.league_id,league:l.name,side:'watch',starter:true,points:null}))});
 return pool.map(p=>({...p,appearances:p.appearances.filter(a=>(S.watchLeague==='all'||a.leagueId===S.watchLeague)&&(S.watchRole==='both'||a.side===S.watchRole||a.side==='watch')&&(a.starter||S.bench))})).filter(p=>p.appearances.length);
}
export function watchCards(pool=watchedPlayers()){
 const autoState=pool.some(p=>p.game?.state==='in')?'in':pool.some(p=>p.game?.state==='pre')?'pre':null;
 const cards=pool.filter(p=>(S.filter==='all'||S.filter==='auto'&&(!autoState||p.game?.state===autoState)||S.filter==='pinned'&&S.pins.has(p.id)||S.filter==='live'&&p.game?.state==='in'||S.filter==='upcoming'&&p.game?.state==='pre'||S.filter==='done'&&p.game?.state==='post')&&`${pname(p.id)} ${p.player.team} ${p.player.number||''} ${p.player.position}`.toLowerCase().includes(S.query.toLowerCase())).sort((a,b)=>(S.pins.has(b.id)-S.pins.has(a.id))||({in:0,pre:1,post:2}[a.game?.state]??3)-({in:0,pre:1,post:2}[b.game?.state]??3)||pname(a.id).localeCompare(pname(b.id)));
 queueMicrotask(()=>{if($('#player-count'))$('#player-count').textContent=cards.length});
 return cards.map(({id,player:p,game:g,appearances})=>{
  const state=g?.state,live=state==='in',label=live?'LIVE':state==='pre'?'UP NEXT':state==='post'?'FINAL':'NO GAME';
  const changes=appearances.map(a=>recentScore(id,a)).filter(Boolean),increase=changes.some(e=>e.delta>0),against=changes.filter(e=>e.delta>0).every(e=>e.side==='opponent'),preview=S.previewPlayer===id,effect=S.prefs.scoreEffects!==false&&(increase||preview);
  return `<article class="player-card compact-card ${effect?'score-up':''} ${effect&&against&&!preview?'opponent-update':''}" data-player-id="${esc(id)}" style="--team:${teamColors[p.team]||'#567587'}"><div class="compact-player"><div class="player-main">${playerPortrait(id,p)}<div class="player-identity"><div class="player-name" title="${esc(pname(id))}">${esc(pname(id))}</div><div class="player-meta">${esc(p.team||'FA')} · ${esc(p.position)}${injury(p)}</div></div></div><button class="pin ${S.pins.has(id)?'on':''}" data-pin="${esc(id)}" aria-label="${S.pins.has(id)?'Unpin':'Pin'} ${esc(pname(id))}" aria-pressed="${S.pins.has(id)}">${S.pins.has(id)?'★':'☆'}</button></div><div class="compact-game"><span class="game-status ${live?'is-live':''}">${label}</span><span title="${esc(g?.detail||'Schedule unavailable')}">${g?`${g.home?'vs':'@'} ${esc(g.opponent)} · ${esc(g.detail)}${g.channel?' · '+esc(g.channel):''}`:'Schedule unavailable'}</span>${preview?'<span class="score-change">PREVIEW</span>':''}</div><div class="compact-score-head"><span>LEAGUE</span><span>PTS / PROJ</span></div>${appearances.map(a=>{
   const l=S.data.leagues.find(l=>l.league_id===a.leagueId),projection=value(id,l),change=recentScore(id,a),progress=Number.isFinite(a.points)&&projection>0?Math.min(100,Math.max(0,a.points/projection*100)):null;
   return `<div class="compact-score-row ${a.side==='opponent'?'against':''}"><div class="compact-league"><span class="role-dot" title="${a.side==='opponent'?'Opponent':a.side==='watch'?'Watchlist':a.starter?'Starter':'Bench'}"></span><span title="${esc(a.league)}">${esc(a.league)}</span>${!a.starter?'<small>BN</small>':''}${a.side==='opponent'?'<small>OPP</small>':''}</div><div class="compact-points">${change?`<span class="score-change ${change.delta<0?'correction':''}" title="${change.delta<0?'Score correction':'Since previous refresh'}">${signed(change.delta)}</span>`:''}<strong title="${esc(a.league)} actual points">${fmt(a.points,2)}</strong><span title="Pregame projection for ${esc(a.league)}"> / ${fmt(projection)}</span></div>${progress!==null?`<div class="projection-progress" aria-hidden="true"><span style="width:${progress}%"></span></div>`:''}</div>`;
  }).join('')}</article>`;
 }).join('')||empty('No players in this view',S.filter==='live'?'No tracked games are live right now. Try Game day or All players.':'Try another filter or include your bench.');
}
